insert into public.card_catalog (bank_name, card_name, network, default_benefits, default_annual_fee, card_color_theme)
values
('Standard Chartered', 'Standard Chartered Manhattan Credit Card', 'Mastercard', '[{"title":"5% Cashback on Grocery Stores","category":"shopping","description":"5% cashback at supermarkets and grocery stores. Capped at ₹500 per month. Capped at ₹500 cashback per month on grocery. Annual fee waived on ₹1.2L annual spend. (5% back (cap ₹500/mo))","value_estimate":500},{"title":"3X Reward Points on Dining & Travel","category":"shopping","description":"3X reward points on dining and travel spends. 1X on all other purchases. Check point value and expiry on Standard Chartered portal. (3X pts (dining/travel))","value_estimate":null}]'::jsonb, 999, 'obsidian'),
('American Express', 'American Express Gold Charge Card', 'Amex', '[{"title":"Domestic Airport Lounge Access","category":"lounge","description":"4 complimentary domestic lounge visits per year via the Amex India lounge program. Maximum 1 visit per quarter. Maximum 1 visit per quarter. Check eligible lounges on Amex India lounge locator. (4 visits/year)","value_estimate":null},{"title":"1 Membership Rewards Point per ₹50 Spent","category":"shopping","description":"Earn 1 Membership Rewards point per ₹50 spent. Bonus 1,000 MR points on 6 transactions of ₹1,000+ per month. Points redeemable for Amazon vouchers (1 point = ₹0.40), Flipkart, travel, or transfer to airline programs. Points never expire. Excludes fuel, insurance, utilities. Points never expire — strong advantage over other cards. (1 MR pt/₹50)","value_estimate":null},{"title":"4,000 Bonus MR Points on ₹4L Spend per 6 Months","category":"shopping","description":"Earn 4,000 bonus Membership Rewards points on spending ₹4 lakh in each 6-month period. Two 6-month windows per anniversary year. Milestone tracked on card anniversary basis. (4,000 bonus MR pts)","value_estimate":null}]'::jsonb, 4500, 'amber')
on conflict (bank_name, card_name) do update set
  network = excluded.network,
  default_benefits = excluded.default_benefits,
  default_annual_fee = excluded.default_annual_fee,
  card_color_theme = excluded.card_color_theme;